{
  "name": "opencode-ollama-qwen-thinking",
  "version": "0.1.3",
  "description": "OpenCode plugin and localhost proxy for Qwen3.8 reasoning levels through Ollama",
  "type": "module",
  "main": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "scripts": {
    "test": "bun test",
    "proxy": "bun run src/proxy.ts",
    "generate:variants": "bun run scripts/generate-qwen-variants.ts",
    "sync:version": "bun run scripts/sync-version.ts",
    "version": "bun run sync:version",
    "prepublishOnly": "bun test"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "@opencode-ai/plugin": "latest"
  },
  "engines": {
    "bun": ">=1.1.26"
  },
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/amit-batra/opencode-ollama-qwen-thinking.git"
  },
  "files": [
    "src",
    "scripts",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "ollama",
    "qwen",
    "qwen3.8",
    "reasoning",
    "llm",
    "ai"
  ],
  "bugs": {
    "url": "https://github.com/amit-batra/opencode-ollama-qwen-thinking/issues"
  },
  "homepage": "https://github.com/amit-batra/opencode-ollama-qwen-thinking"
}
